"""Shared node harness pieces for the settings-tool JavaScript pins.

The settings-page pins in ``test_cinbase_extend_table_format.py``,
``test_cinbase_candidate_font_style.py`` and ``test_config_tool_js.py`` all
drive ``python/cinbase/config/js/config.js`` through the bundled
``node/node.exe``: read the file, stub the handful of DOM/jQuery touches the
script makes at load, ``eval`` the source, then call the functions under pin.
This module holds that common prelude and the one subprocess runner; each
test file keeps its own assertion list on top.

Not a ``test_*.py`` module, so ``unittest discover`` ignores it.
"""

import json
import os
import subprocess

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
NODE = os.path.join(ROOT, "node", "node.exe")

TIMEOUT_SECONDS = 60


def settings_prelude(script_path, inputs=None, selects=None):
    """Return the shared node -e prelude lines for a settings script.

    The stubs cover exactly the statements ``config.js`` runs at load
    (the ``hasInnerText`` read, the ``isIE`` probe, ``includeScriptFile``,
    ``loadConfig``) plus the touches the pinned functions make: ``$.jAlert``
    collects the error texts, the ``$(elementId)`` object answers
    blur()/prop()/val() on the error path, and ``$( sel )`` iterates the
    caller-supplied ``inputs``/``selects`` arrays through ``each`` the way
    the save loop expects. ``inputs``/``selects`` are JSON-serialisable
    values rendered straight into the script; omit them for the empty
    default that a caller reassigns per scenario.
    """
    js_path = script_path.replace("\\", "/")
    return [
        "var src = require('fs').readFileSync(%s, 'utf8');" % json.dumps(js_path),
        "var alerts = [];",
        # Faithful to jquery-1.12.4's isNumeric.
        "function isNumeric(obj) { return !isNaN(parseFloat(obj)) && isFinite(obj); }",
        # config.js touches the DOM at load; these stubs answer exactly
        # the statements that run (isIE, includeScriptFile, loadConfig).
        "var document = {",
        "  getElementsByTagName: function () { return [{ innerText: '' }]; },",
        "  createElement: function () { return { innerHTML: '',",
        "    getElementsByTagName: function () { return []; } }; } };",
        "Object.defineProperty(globalThis, 'navigator', { value:",
        "  { userAgent: 'node', appVersion: 'Trident/7.0' },",
        "  configurable: true, writable: true });",
        "function includeScriptFile() {}",
        "$.get = function (url, cb, type) { };",
        "$.jAlert = function (opts) { alerts.push(opts.content); };",
        "var inputs = %s;" % json.dumps(inputs if inputs is not None else []),
        "var selects = %s;" % json.dumps(selects if selects is not None else []),
        "function $(sel) {",
        "  if (typeof sel === 'function') { return; }",
        "  return { each: function (cb) {",
        "    (sel === 'input' ? inputs : selects).forEach(",
        "      function (it, i) { cb(i, it); }); },",
        "    blur: function () {}, prop: function () {}, val: function () { return ''; } };",
        "}",
        "$.isNumeric = isNumeric;",
        "eval(src);",
    ]


def run_node_script(harness):
    """Run ``harness`` under the bundled node and return its JSON output.

    The skip/fail style is the one the three settings pins already use, so
    a machine without the vendored toolchain reports SKIP instead of
    failing; the raises work from both ``setUpClass`` and test methods.
    """
    if not os.path.isfile(NODE):
        raise unittest.SkipTest("no bundled node/node.exe on this machine")
    try:
        completed = subprocess.run(
            [NODE, "-e", harness],
            cwd=ROOT,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            timeout=TIMEOUT_SECONDS,
        )
    except OSError as error:
        raise unittest.SkipTest("bundled node.exe cannot run here: %s" % error)
    except subprocess.TimeoutExpired:
        raise AssertionError("node -e for the settings script timed out after %ss"
                             % TIMEOUT_SECONDS)
    stdout = completed.stdout.decode("utf-8", "replace")
    if completed.returncode != 0:
        raise AssertionError("node -e failed: %s" % stdout)
    return json.loads(stdout)
